class Solution {
  public int minOperations(String s) {
    // every letter must travel forward to 'a'; shared steps merge, so the furthest letter decides
    int best = 0;
    for (int i = 0; i < s.length(); i++) {
      int c = s.charAt(i) - 'a';
      if (c != 0) best = Math.max(best, 26 - c);
    }
    return best;
  }
}
